\label{scal}
    \( E_c^\pm \) and \( E_1^\pm \) are isometrically isomorphic under the following scaling transformation
    $$  T_c(u)(x)=  c^{-1/2}u(c^{-1}x),\quad \forall u\in E_c.$$
    \begin{proof}

For $u\in E_c$, we have
\begin{equation}
    \begin{split}
        \widehat{P_1^\pm T_c(u)}(\xi)&= 
        \frac{c^{-1/2}}{2}\left(I_4\pm\frac{m}{\lambda_1}\beta\pm\frac{1 }{\lambda_1}\alpha\cdot \xi\right)\widehat{T_c(u)}(\xi)\\
        &= \frac{c^{5/2}}{2}\left(I_4\pm\frac{mc^2}{\lambda_c(c\xi)}\beta\pm\frac{c }{\lambda_c(c\xi)}\alpha\cdot (c\xi)\right)\hat{u}(c\xi)\\
        &={c^{5/2}}\widehat{P_c^\pm u}(c\xi)
    \end{split}
\end{equation}
Hence, 
$$
(P_1^\pm T_c(u))(x) = c^{-1/2}(P_c^\pm u) (c^{-1}x)= T_c(P_c^{\pm}(u))(x),
$$
which implies $T_c(u)\in E_1^\pm$ if and only if $u\in E_c^\pm$. In addition, we have
\begin{equation}
    \begin{split}
        \|T_c(u)\|_1^2 &=\int_{\mathbb{R}^3}\sqrt{|\xi|^2+ m^2}|\widehat{T_c(u)}|^2(\xi) d \xi
        \\
&=\int_{\mathbb{R}^3}\sqrt{c^2|\xi|^2+ m^2c^4}|\widehat{u}|^2(\xi) d \xi\\
        &=\|u\|_c^2.
    \end{split}
\end{equation}
Therefore, we have that \( T_c \) is an isometric isomorphism from \( E_c^\pm \) to \( E_1^\pm \).    
    \end{proof}

