\label{new_lpp}
  There exists $c_0>0$, such that for $c>c_0,\,1<p<\infty$, there holds
  \begin{equation}\label{new_lp1}
    \| (\mathscr{D}_c- mc^2 + 1)^{-1} u\|_{W^{1,p}}\leq  C   \|u\|_{L^p},
  \end{equation}
 \begin{equation}\label{new_lp2}
  \|P_c^- (\mathscr{D}_c- mc^2 + 1)^{-1} u\|_{W^{1,p}}\leq \frac{ C  }{c}\|u\|_{L^p},
 \end{equation}
  and 
  \begin{equation}\label{new_lp3}
    \|P_c^- (\mathscr{D}_c- mc^2 + 1)^{-1} u\|_{L^p}\leq \frac{ C  }{c^2}\|u\|_{L^p}.
  \end{equation}
\begin{proof}
  The operators \({\sqrt{-\Delta+1}}\left(|\mathscr{D}_c|+ mc^2 - 1\right)^{-1}\) and
   \(\left({|\mathscr{D}_c|+ mc^2 - 1}\right)^{-1}\) are associated with the symbols  
\[
f(\xi)=\frac{\sqrt{|\xi|^2+1}}{\sqrt{c^2|\xi|^2+ m^2c^4}+mc^2-1}, \quad g(\xi)=\frac{1}{\sqrt{c^2|\xi|^2+ m^2c^4}+mc^2-1},
\]
respectively. A direct computation shows that for all multi-indices \(\alpha\) with \(0 \leq |\alpha| \leq 2\), the following estimates hold for all \(\xi \in \mathbb{R}^{n} \setminus \{0\}\):
\[
|\nabla^{\alpha}f(\xi)| \leq \frac{C}{c|\xi|^{|\alpha|}}, \quad |\nabla^{\alpha}g(\xi)| \leq \frac{C}{c^2|\xi|^{|\alpha|}},
\]
where \(C\) is a constant independent of \(\xi\) and \(c\). By Lemma \ref{com} and
Mikhlin–Hörmander multiplier theorem (see Theorem 5.2.7 in \cite{MR3243734}),
there holds
\begin{equation*}
  \begin{split}
    \|P_c^- (\mathscr{D}_c- mc^2 + 1)^{-1} u\|_{W^{1,p}}
    &=\| (|\mathscr{D}_c|+ mc^2 - 1)^{-1} u^-\|_{W^{1,p}}\\
    &\leq \frac{ C  }{c}\|u^-\|_{L^p}\\
    & \leq \frac{ C  }{c}\|u\|_{L^p},
  \end{split}
\end{equation*}
and 
\begin{equation*}
  \begin{split}
    \|P_c^- (\mathscr{D}_c- mc^2 + 1)^{-1} u\|_{L^p}
    &=\| (|\mathscr{D}_c|+ mc^2 - 1)^{-1} u^-\|_{L^p}\\
    &\leq \frac{ C  }{c^2}\|u^-\|_{L^p}\\
    & \leq \frac{ C  }{c^2}\|u\|_{L^p},
  \end{split}
\end{equation*}
Combining \eqref{new_lp0} with \eqref{new_lp2}, we obtain 
\begin{equation*}
  \begin{split}
    \| (\mathscr{D}_c- mc^2 + 1)^{-1} u\|_{W^{1,p}}&\leq \| P_c^+(\mathscr{D}_c- mc^2 + 1)^{-1} u\|_{W^{1,p}}+ \| P_c^-(\mathscr{D}_c- mc^2 + 1)^{-1} u\|_{W^{1,p}}\\
    & = \| (|\mathscr{D}_c|- mc^2 + 1)^{-1} u^+\|_{W^{1,p}} + \| P_c^-(\mathscr{D}_c- mc^2 + 1)^{-1} u\|_{W^{1,p}}\\
    &\leq  C   \|u\|_{L^p}.
  \end{split}
\end{equation*}
This ends the proof.
\end{proof}

