\begin{equation}\label{prop3.3.1}
\begin{aligned}
d^2\mathcal{I}^{c,\tau}(u)[h, h]
&= a^{-1} b \, d^2\mathcal{I}^{c,\tau}(u)[u, (b w - a^{-1} b \eta)] \\
&\quad + 2 d^2\mathcal{I}^{c,\tau}(u)[b w, \xi] + a^{-2} b^2 d^2\mathcal{I}^{c,\tau}(u)[\eta, \eta] + d^2\mathcal{I}^{c,\tau}(u)[\xi, \xi],
\end{aligned}
\end{equation}
where the second derivative is given by
\begin{equation}\label{second_de}
\begin{split}
d^2\mathcal{I}^{c,\tau}(u)[h, k]
&= 2 (h^+, k^+)_c - 2 (h^-, k^-)_c - 2\tau^{\zeta} \int_{\mathbb{R}^3} |u|^{p-2} \Re\langle h, k \rangle \, dx \\
&\quad - 2(p - 2)\tau^{\zeta} \int_{\mathbb{R}^3} |u|^{p-4} \Re\langle u, h \rangle \cdot \Re\langle u, k \rangle \, dx.
\end{split}
\end{equation}
