&= 2 d\mathcal{I}^{c,\tau}(u)[h] - 2 (u^+, h^+)_c + 2 (u^-, h^-)_c \\
&\quad - 2(p - 3)\tau^{\zeta} \int_{\mathbb{R}^3} |u|^{p-2} \Re\langle u, h \rangle \, dx.
\end{split}
\end{equation}

