            \hat{u}(\lambda^{1/2} \xi), \hat{u}(\lambda^{-1/2} \xi) \right)_{L^2} \\
        &= - (\mathscr{D}_c u, u)_{L^2} - \frac{1}{2} (m c^2 \beta u, u)_{L^2}.
