&= t^2 \int_{\mathbb{R}^3} \left( \left| \nabla \sqrt{|f_1|^2 + |f_2|^2} \,\right|^2 + |f_1|^2 + |f_2|^2 \right) dx - \frac{2t^p}{p} \int_{\mathbb{R}^3} \big( |f_1|^2 + |f_2|^2 \big)^{\frac{p}{2}} dx \\
&= \left( 1 - \frac{2}{p} \right) t^2 \int_{\mathbb{R}^3} \left( \left| \nabla \sqrt{|f_1|^2 + |f_2|^2} \,\right|^2 + |f_1|^2 + |f_2|^2 \right) dx \\
&\leq \left( 1 - \frac{2}{p} \right) t^2 \int_{\mathbb{R}^3} \left( |\nabla f_1|^2 + |\nabla f_2|^2 + |f_1|^2 + |f_2|^2 \right) dx \\
&= t^2 \, e^\infty_{\lambda,2} \leq e^\infty_{\lambda,2}.
    \end{split}
\end{equation}
On the other hand, since $H^1(\mathbb{R}^3, \mathbb{R})$ can be embedded into $H^1(\mathbb{R}^3, \mathbb{C}^2)$, we have $e^\infty_{\lambda,1} \geq e^\infty_{\lambda,2}$. Hence, $e^\infty_{\lambda,1} = e^\infty_{\lambda,2}$. A similar argument shows that $e^\infty_{\lambda,1} = e^\infty_{\lambda,3}$.

It is easy to see that equality holds in \eqref{B_2} if and only if 
\begin{equation}\label{B_3}
    \int_{\mathbb{R}^3} \left| \nabla \sqrt{|f_1|^2 + |f_2|^2} \,\right|^2 dx = \int_{\mathbb{R}^3} \left( |\nabla f_1|^2 + |\nabla f_2|^2 \right) dx,
\end{equation}
 and up to translation,
 \begin{equation}\label{B_4}
     f= \sqrt{|f_1|^2+ |f_2|^2}.
 \end{equation}
By \cite[Theorem 6.17]{MR1817225}, \eqref{B_3} is satisfied if and only if the real and imaginary parts of \( f_1 \) and \( f_2 \) are proportional, i.e., \(\Re f_1, \Im f_1, \Re f_2, \Im f_2\) are linearly dependent. Moreover, from \eqref{B_4}, we conclude that there exist constants \( a, b \in \mathbb{C} \) with \( |a|^2 + |b|^2 = 1 \) such that \( (f_1, f_2) = (a f, b f) \). This implies that \( (f_1, f_2)^T = \gamma \cdot (f, 0)^T \) for some \( \gamma \in \mathrm{SU}(2) \). Similarly, the action ground state of \( \mathcal{J}^\infty_{\lambda, 3} \) can be generated from the action ground state of \( \mathcal{J}^\infty_{\lambda, 1} \) through the action of \( \mathrm{SU}(4) \).

\begin{equation}\label{B_2}
    \begin{split}
        e^\infty_{\lambda,1} 
&\leq \mathcal{J}^\infty_{\lambda,1} \left( t \sqrt{|f_1|^2 + |f_2|^2} \right) \\
&= t^2 \int_{\mathbb{R}^3} \left( \left| \nabla \sqrt{|f_1|^2 + |f_2|^2} \,\right|^2 + |f_1|^2 + |f_2|^2 \right) dx - \frac{2t^p}{p} \int_{\mathbb{R}^3} \big( |f_1|^2 + |f_2|^2 \big)^{\frac{p}{2}} dx \\
&= \left( 1 - \frac{2}{p} \right) t^2 \int_{\mathbb{R}^3} \left( \left| \nabla \sqrt{|f_1|^2 + |f_2|^2} \,\right|^2 + |f_1|^2 + |f_2|^2 \right) dx \\
&\leq \left( 1 - \frac{2}{p} \right) t^2 \int_{\mathbb{R}^3} \left( |\nabla f_1|^2 + |\nabla f_2|^2 + |f_1|^2 + |f_2|^2 \right) dx \\
&= t^2 \, e^\infty_{\lambda,2} \leq e^\infty_{\lambda,2}.
    \end{split}
\end{equation}
